var fields = jsonData;


    var expectedFields = [
        { dataElementName: "Global_SpouseMonthlyGrossIncome", dataFormat: "Currency", value: "11,500", textLabel: "Monthly gross income" },
        { dataElementName: "MonthlyEmploymentTaxes", dataFormat: "Currency", value: "1,033", textLabel: "Less employment taxes" },
        { dataElementName: "MonthlyIncomeTaxes", dataFormat: "Currency", value: "2,592", textLabel: "Less income taxes" },
        { dataElementName: "MonthlyExtraExpenses", dataFormat: "Currency", value: "2,820", textLabel: "Less extra expenses if work" },
        { dataElementName: "MonthlyExtraExp_AtHome", dataFormat: "Currency", value: "2,300", textLabel: "Plus extra expenses if stay at home" },
        { dataElementName: "MonthlyGain", dataFormat: "Currency", value: "7,355", textLabel: "<b>Monthly benefits from working</b>" }
    ];


    for (var i = 0; i < fields.length; i++) {
        pm.expect(fields[i].dataElementName, `Failed for "${fields[i].dataElementName}" - dataElementName`).to.eql(expectedFields[i].dataElementName);
        pm.expect(fields[i].dataFormat, `Failed for "${fields[i].dataElementName}" - dataFormat`).to.eql(expectedFields[i].dataFormat);
        pm.expect(fields[i].value, `Failed for "${fields[i].dataElementName}" - value`).to.eql(expectedFields[i].value);
        pm.expect(fields[i].textLabel, `Failed for "${fields[i].dataElementName}" - textLabel`).to.eql(expectedFields[i].textLabel);
    }
